def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    pattern_colors = [v for v in counts if v not in (bg, 0, 2)]
    if not pattern_colors:
        return [row[:] for row in grid]
    pattern_color = max(pattern_colors, key=lambda v: counts[v])

    pattern = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] == pattern_color
    }
    seed_cells = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] == 2
    }

    def components(cells):
        unseen = set(cells)
        result = []
        while unseen:
            start = min(unseen)
            unseen.remove(start)
            stack = [start]
            comp = {start}
            while stack:
                r, c = stack.pop()
                for q in ((r - 1, c), (r + 1, c),
                          (r, c - 1), (r, c + 1)):
                    if q in unseen:
                        unseen.remove(q)
                        comp.add(q)
                        stack.append(q)
            result.append(comp)
        return result

    def intervals(values):
        values = sorted(set(values))
        if not values:
            return []
        result = []
        lo = hi = values[0]
        for x in values[1:]:
            if x == hi + 1:
                hi = x
            else:
                result.append((lo, hi))
                lo = hi = x
        result.append((lo, hi))
        return result

    pattern_components = components(pattern)
    seeds = components(seed_cells)
    gates = []

    for comp in pattern_components:
        rows = {}
        cols = {}
        for r, c in comp:
            rows.setdefault(r, []).append(c)
            cols.setdefault(c, []).append(r)
        row_runs = {r: intervals(cs) for r, cs in rows.items()}

        # Gates with a horizontal closed bar and vertical rails.
        for r in sorted(rows):
            for left, right in row_runs[r]:
                if right - left + 1 < 5:
                    continue

                down_rails = []
                up_rails = []
                for c in range(left + 1, right):
                    length = 0
                    rr = r + 1
                    while (rr, c) in comp:
                        length += 1
                        rr += 1
                    if length >= 2:
                        down_rails.append((c, length))

                    length = 0
                    rr = r - 1
                    while (rr, c) in comp:
                        length += 1
                        rr -= 1
                    if length >= 2:
                        up_rails.append((c, length))

                # Open toward the south: the bump is just below the bar.
                for i in range(len(down_rails)):
                    for j in range(i + 1, len(down_rails)):
                        a, la = down_rails[i]
                        b, lb = down_rails[j]
                        if a >= b:
                            continue
                        inner = [c for c in range(a + 1, b)
                                 if (r + 1, c) in comp]
                        for x1, x2 in intervals(inner):
                            bump = {(r + 1, c) for c in range(x1, x2 + 1)}
                            gates.append({
                                "axis": "v", "move": (-1, 0),
                                "bump": bump,
                                "cols": set(range(x1, x2 + 1)),
                                "limit": max(r + la, r + lb),
                                "kind": "south",
                            })

                # Open toward the north: the bump is just above the bar.
                for i in range(len(up_rails)):
                    for j in range(i + 1, len(up_rails)):
                        a, la = up_rails[i]
                        b, lb = up_rails[j]
                        if a >= b:
                            continue
                        inner = [c for c in range(a + 1, b)
                                 if (r - 1, c) in comp]
                        for x1, x2 in intervals(inner):
                            bump = {(r - 1, c) for c in range(x1, x2 + 1)}
                            gates.append({
                                "axis": "v", "move": (1, 0),
                                "bump": bump,
                                "cols": set(range(x1, x2 + 1)),
                                "limit": min(r - la, r - lb),
                                "kind": "north",
                            })

        # Gates with a vertical spine and two horizontal rails.
        for c in sorted(cols):
            for top, bottom in intervals(cols[c]):
                if bottom - top + 1 < 5:
                    continue

                arms = []
                for r in range(top, bottom + 1):
                    for left, right in row_runs.get(r, []):
                        if not (left <= c <= right) or right - left + 1 < 4:
                            continue
                        if left == c and right - c >= 2:
                            arms.append((r, 1, left, right))
                        elif right == c and c - left >= 2:
                            arms.append((r, -1, left, right))

                for i in range(len(arms)):
                    for j in range(i + 1, len(arms)):
                        r1, side1, left1, right1 = arms[i]
                        r2, side2, left2, right2 = arms[j]
                        if side1 != side2 or r2 - r1 < 3:
                            continue

                        bump = set()
                        bump_rows = set()
                        for r in range(r1 + 1, r2):
                            cc = c + side1
                            while (r, cc) in comp:
                                bump.add((r, cc))
                                bump_rows.add(r)
                                cc += side1

                        if not bump_rows:
                            continue
                        if set(range(min(bump_rows), max(bump_rows) + 1)) != bump_rows:
                            continue

                        if side1 > 0:
                            edge = max(right1, right2)
                        else:
                            edge = min(left1, left2)

                        gates.append({
                            "axis": "h",
                            "move": (0, -side1),
                            "bump": bump,
                            "bump_rows": bump_rows,
                            "side": side1,
                            "edge": edge,
                        })

    def roll(seed, move):
        dr, dc = move
        current = set(seed)
        path = set(current)
        steps = 0
        while True:
            nxt = {(r + dr, c + dc) for r, c in current}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in nxt):
                return None
            hit = nxt & pattern
            if hit:
                return current, path, hit, steps
            current = nxt
            path.update(current)
            steps += 1

    candidates = []
    for si, seed in enumerate(seeds):
        rs = [r for r, c in seed]
        cs = [c for r, c in seed]
        minr, maxr = min(rs), max(rs)
        minc, maxc = min(cs), max(cs)

        for gate in gates:
            if gate["axis"] == "v":
                if not set(range(minc, maxc + 1)).issubset(gate["cols"]):
                    continue
                if gate["kind"] == "south" and minr <= gate["limit"]:
                    continue
                if gate["kind"] == "north" and maxr >= gate["limit"]:
                    continue
            else:
                if not set(range(minr, maxr + 1)).issubset(gate["bump_rows"]):
                    continue
                if gate["side"] > 0 and minc <= gate["edge"]:
                    continue
                if gate["side"] < 0 and maxc >= gate["edge"]:
                    continue

            result = roll(seed, gate["move"])
            if result is None:
                continue
            final, path, hit, steps = result
            if steps > 0 and hit and hit.issubset(gate["bump"]):
                candidates.append((steps, si, final, path, gate["move"]))

    candidates.sort(key=lambda x: (x[0], x[1]))
    chosen = {}
    for item in candidates:
        if item[1] not in chosen:
            chosen[item[1]] = item

    out = [row[:] for row in grid]
    for r, c in seed_cells:
        out[r][c] = bg

    for _, _, final, path, _ in chosen.values():
        for r, c in path:
            out[r][c] = 0
        for r, c in final:
            out[r][c] = 2

    return out
